# SPDX-License-Identifier: AGPL-3.0-or-later
#
# Cross-language parity for geron_ml2_native.R.
#
# Every `A[[...]]` anchor in anchors.R was GENERATED by running the
# canonical Python from the repository root:
#
#   cd <repo> && MORIE_NO_UPDATE_CHECK=1 PYTHONPATH=src \
#     python3 tools/gen_anchors.py > anchors.R
#
# and the generator asserts `module.__file__` contains "/src/morie/fn/"
# before reading a single value, so a stale installed morie cannot
# silently supply the numbers.
#
# Beyond value-for-value parity, each family is also checked against an
# INDEPENDENT route computed here in R: parameter counts against layer
# algebra, Gini against the hand formula, the exact value function
# against iterated policy evaluation, activation derivatives against
# central finite differences, and the tabular RL updates replayed
# draw-for-draw.

TOL <- 1e-9

expect_close <- function(object, expected, tol = TOL) {
  testthat::expect_equal(as.numeric(object), as.numeric(expected),
                         tolerance = tol)
}

test_that("ELU, SELU, GELU, leaky ReLU, sigmoid, tanh, swish match Python", {
  zs <- c(-2, -1, -0.5, 0, 0.5, 1, 2, 3.5)
  r <- morie_geron_elu(zs, alpha = 1.5)
  expect_close(r$a, A[["elu.a"]])
  expect_close(r$derivative, A[["elu.d"]])
  expect_close(r$estimate, A[["elu.est"]])
  expect_false(r$is_c1)

  r <- morie_geron_selu(zs)
  expect_close(r$a, A[["selu.a"]])
  expect_close(r$grad, A[["selu.grad"]])
  expect_close(r$var, A[["selu.var"]])

  r <- morie_geron_gelu(zs)
  expect_close(r$exact, A[["gelu.exact"]])
  expect_close(r$approx, A[["gelu.approx"]])
  expect_close(r$derivative, A[["gelu.deriv"]])
  expect_close(r$max_abs_gap, A[["gelu.gap"]])

  r <- morie_geron_heaviside(c(-1, 0, 2), at_zero = 0.5)
  expect_close(r$activation, A[["hev.a"]])
  expect_close(r$n_active, A[["hev.n_active"]])

  r <- morie_geron_leaky_relu(zs, alpha = 0.05)
  expect_close(r$activation, A[["lrel.a"]])
  expect_close(r$derivative, A[["lrel.d"]])
  expect_close(r$n_leaky, A[["lrel.n_leaky"]])

  r <- morie_geron_sigmoid(zs)
  expect_close(r$a, A[["sigm.a"]])
  expect_close(r$grad, A[["sigm.grad"]])

  r <- morie_geron_tanh(zs)
  expect_close(r$a, A[["tanh.a"]])
  expect_close(r$grad, A[["tanh.grad"]])

  r <- morie_geron_swish(zs, beta = 1.3)
  expect_close(r$a, A[["swi.a"]])
  expect_close(r$grad, A[["swi.grad"]])
  expect_close(r$gate, A[["swi.gate"]])
})

test_that("activation derivatives survive central finite differences", {
  # INDEPENDENT ROUTE: the analytic derivative each module returns is
  # checked against (f(z+h) - f(z-h)) / 2h, never against Python.
  h <- 1e-6
  zs <- c(-2, -1, -0.5, 0.5, 1, 2, 3.5)   # 0 excluded: leaky ReLU kinks there
  fd <- function(f) (f(zs + h) - f(zs - h)) / (2 * h)

  expect_close(morie_geron_elu(zs, alpha = 1.5)$derivative,
               fd(function(z) morie_geron_elu(z, alpha = 1.5)$a), tol = 1e-6)
  expect_close(morie_geron_selu(zs)$grad,
               fd(function(z) morie_geron_selu(z)$a), tol = 1e-6)
  expect_close(morie_geron_gelu(zs)$derivative,
               fd(function(z) morie_geron_gelu(z)$exact), tol = 1e-6)
  expect_close(morie_geron_sigmoid(zs)$grad,
               fd(function(z) morie_geron_sigmoid(z)$a), tol = 1e-6)
  expect_close(morie_geron_tanh(zs)$grad,
               fd(function(z) morie_geron_tanh(z)$a), tol = 1e-6)
  expect_close(morie_geron_swish(zs, beta = 1.3)$grad,
               fd(function(z) morie_geron_swish(z, beta = 1.3)$a), tol = 1e-6)
  expect_close(morie_geron_leaky_relu(zs, alpha = 0.05)$derivative,
               fd(function(z) morie_geron_leaky_relu(z, alpha = 0.05)$activation),
               tol = 1e-6)

  # GELU really is non-monotone: the derivative dips below zero.
  expect_true(any(morie_geron_gelu(seq(-2, -0.2, by = 0.1))$derivative < 0))
})

test_that("TLU, softmax and softmax scores match Python", {
  r <- morie_geron_tlu(matrix(c(1, -2, 0.5, 0.5, -1, -1), nrow = 3, byrow = TRUE),
                       c(1, 1), b = 0.25)
  expect_close(r$y, A[["tlu.y"]])
  expect_close(r$z, A[["tlu.z"]])

  r <- morie_geron_softmax_function(c(1, 2, 0.5))
  expect_close(r$p, A[["sftm.p"]])
  expect_close(r$jacobian, A[["sftm.jac"]])
  expect_equal(r$argmax, as.integer(A[["sftm.argmax"]]))
  expect_close(sum(r$p), 1)

  r <- morie_geron_softmax_function(matrix(c(1, 2, 0.5, 0, 0, 3), nrow = 2, byrow = TRUE))
  expect_close(r$p, A[["sftm.P2"]])
  expect_equal(as.integer(r$argmax), as.integer(A[["sftm.am2"]]))
  expect_close(rowSums(r$p), c(1, 1))

  r <- morie_geron_softmax_score(matrix(c(1, 2, 0.5, -1), nrow = 2, byrow = TRUE),
                                 matrix(c(0.3, -0.2, 0.5, 1, 0.4, -0.7), nrow = 2,
                                        byrow = TRUE))
  expect_close(r$scores, A[["sfts.scores"]])
  expect_close(r$p, A[["sfts.p"]])
  expect_equal(as.integer(r$predicted), as.integer(A[["sfts.pred"]]))
  expect_close(r$estimate, A[["sfts.est"]])
  # softmax is monotone, so argmax score == argmax probability
  expect_equal(as.integer(r$predicted), apply(r$p, 1, which.max) - 1L)
})

test_that("Gini and entropy match Python and the hand formula", {
  y <- c(0, 0, 1, 1, 1, 2)
  g <- morie_geron_gini_impurity(y)
  expect_close(g$gini, A[["gini.g"]])
  expect_close(g$proportions, A[["gini.p"]])
  expect_close(g$max_possible, A[["gini.max"]])
  # INDEPENDENT ROUTE: 1 - sum p^2 spelled out by hand.
  p <- c(2, 3, 1) / 6
  expect_close(g$gini, 1 - sum(p^2))

  e <- morie_geron_entropy_impurity(y)
  expect_close(e$entropy, A[["ent.h"]])
  expect_close(e$entropy_nats, A[["ent.nats"]])
  expect_close(e$max_possible, A[["ent.max"]])
  expect_close(e$entropy, -sum(p * log2(p)))
  expect_close(e$entropy_nats, e$entropy * log(2))
  # pure node: both impurities are exactly zero
  expect_close(morie_geron_gini_impurity(rep(1, 5))$gini, 0)
  expect_close(morie_geron_entropy_impurity(rep(1, 5))$entropy, 0)
})

test_that("RMSE and MAE match Python and their own definitions", {
  yt <- c(1, 2, 3, 4); yp <- c(1.5, 1, 3.2, 7)
  r <- morie_geron_rmse(yt, yp)
  expect_close(r$rmse, A[["rms.rmse"]])
  expect_close(r$mse, A[["rms.mse"]])
  expect_close(r$mae, A[["rms.mae"]])
  expect_close(r$rmse, sqrt(mean((yp - yt)^2)))

  m <- morie_geron_mae(yt, yp)
  expect_close(m$mae, A[["mae.mae"]])
  expect_close(m$ratio, A[["mae.ratio"]])
  expect_close(m$median_absolute_error, A[["mae.med"]])
  expect_true(m$rmse >= m$mae)   # l2 dominates l1
})

test_that("linear-model costs, OLS and ridge match Python", {
  X <- matrix(c(1, 0.5, 1, 1.5, 1, 2.5, 1, 4), nrow = 4, byrow = TRUE)
  y <- c(1, 2.2, 2.8, 4.4)

  r <- morie_geron_linreg_mse_cost(X, y, c(0.5, 0.8))
  expect_close(r$cost, A[["msec.cost"]])
  expect_close(r$gradient, A[["msec.grad"]])
  expect_close(r$residuals, A[["msec.resid"]])

  r <- morie_geron_normal_equation(X, y)
  expect_close(r$theta, A[["neq.theta"]])
  expect_close(r$rss, A[["neq.rss"]])
  expect_close(r$cond, A[["neq.cond"]], tol = 1e-7)
  # INDEPENDENT ROUTE: at the OLS solution the MSE gradient vanishes.
  expect_close(morie_geron_linreg_mse_cost(X, y, r$theta)$gradient, c(0, 0), tol = 1e-8)

  r <- morie_geron_ridge_cost(X, y, c(0.5, 0.8), 0.4)
  expect_close(r$cost, A[["ridg.cost"]])
  expect_close(r$penalty, A[["ridg.pen"]])
  expect_close(r$gradient, A[["ridg.grad"]])

  r <- morie_geron_ridge_normal(X, y, 0.4)
  expect_close(r$theta, A[["ridn.theta"]])
  expect_close(r$effective_df, A[["ridn.edf"]])
  expect_close(r$rss, A[["ridn.rss"]])
  # INDEPENDENT ROUTE: the ridge cost gradient is zero at the closed
  # form -- but ONLY after rescaling alpha. hmridg penalises a MEAN
  # squared error with (alpha/2)||theta||^2, while hmridn adds alpha to
  # the RSS normal equations, so the same nominal alpha is a different
  # amount of shrinkage in the two modules; the equivalent cost-form
  # alpha is 2*alpha/m. This convention gap is a property of the Python
  # modules, reproduced faithfully here rather than papered over.
  m <- nrow(X)
  expect_close(morie_geron_ridge_cost(X, y, r$theta, 2 * 0.4 / m)$gradient,
               c(0, 0), tol = 1e-8)
  # and the shrinkage is real: |theta_ridge| < |theta_ols| off the intercept
  expect_true(abs(r$theta[2]) < abs(morie_geron_normal_equation(X, y)$theta[2]))
})

test_that("L1, max-norm and gradient clipping match Python", {
  r <- morie_geron_l1_regularization(c(1.5, -0.3, 0.05, 0), 0.2, skip_bias = TRUE)
  expect_close(r$penalty, A[["l1r.pen"]])
  expect_close(r$gradient, A[["l1r.grad"]])
  expect_close(r$prox, A[["l1r.prox"]])
  expect_close(r$n_zero, A[["l1r.nzero"]])

  W <- matrix(c(3, 4, 0.3, 0.4), nrow = 2, byrow = TRUE)
  r <- morie_geron_max_norm(W, 2, axis = 1)
  expect_close(r$w, A[["mnr.w"]])
  expect_close(r$norm_before, A[["mnr.before"]])
  expect_close(r$norm_after, A[["mnr.after"]])
  expect_close(r$n_clipped, A[["mnr.nclip"]])
  # projection preserves direction exactly
  expect_close(r$w[1, ] / sqrt(sum(r$w[1, ]^2)), W[1, ] / sqrt(sum(W[1, ]^2)))

  r <- morie_geron_max_norm(c(3, 4), 2)
  expect_close(r$w, A[["mnr.flatw"]])
  expect_close(r$norm_before, A[["mnr.flatbefore"]])

  r <- morie_geron_gradient_clipping(c(3, 4), 2.5)
  expect_close(r$clipped, A[["gcl.clipped"]])
  expect_close(r$total_norm, A[["gcl.total"]])
  expect_close(r$scale, A[["gcl.scale"]])
  expect_close(r$new_norm, 2.5)
  expect_close(morie_geron_gradient_clipping(c(3, 4), 2.5, norm_type = Inf)$total_norm,
               A[["gcl.inf_total"]])
})

test_that("learning-rate schedules match Python", {
  r <- morie_geron_lr_exponential(0.1, 0.9, c(0, 1, 5, 10))
  expect_close(r$eta, A[["lrex.eta"]])
  expect_close(r$steps_per_decade, A[["lrex.spd"]])
  expect_true(is.infinite(morie_geron_lr_exponential(0.1, 1, 3)$steps_per_decade))

  r <- morie_geron_learning_rate_schedule(c(0, 1, 4), 1, 2)
  expect_close(r$eta, A[["lrs.eta"]])
  expect_close(r$schedule, A[["lrs.sched"]])
  expect_close(r$sum_eta, A[["lrs.sum"]])
  expect_close(r$sum_eta_squared, A[["lrs.sum2"]])

  r <- morie_geron_cosine_annealing(c(0, 3, 10), 10, 0.5, 0.05)
  expect_close(r$eta, A[["lcos.eta"]])
  expect_close(r$schedule, A[["lcos.sched"]])
  # endpoints are exact by construction
  expect_close(r$schedule[1], 0.5)
  expect_close(r$schedule[11], 0.05)
})

test_that("capacity heuristics match Python and layer algebra", {
  r <- morie_geron_neurons_per_layer(5, n_layers = 3, n_outputs = 2)
  expect_close(r$width, A[["npl.width"]])
  expect_close(r$n_parameters, A[["npl.params"]])
  expect_close(r$parameters_per_layer, A[["npl.per"]])
  # INDEPENDENT ROUTE: count the parameters layer by layer by hand.
  d <- 5; w <- 10; L <- 3; k <- 2
  by_hand <- (d * w + w) + 2 * (w * w + w) + (w * k + k)
  expect_close(r$n_parameters, by_hand)

  r <- morie_geron_overfitting(c(0.4, 0.3, 0.2, 0.1), c(0.5, 0.35, 0.36, 0.45),
                               tol = 0.02)
  expect_close(r$gap, A[["ovf.gap"]])
  expect_close(r$best_epoch, A[["ovf.best"]])
  expect_close(r$epochs_past_best, A[["ovf.past"]])
  expect_close(r$ratio, A[["ovf.ratio"]])
  expect_true(r$overfitting)
  expect_equal(r$verdict, A[["ovf.verdict"]])

  r <- morie_geron_underfitting(c(0.9, 0.85, 0.84, 0.84), threshold = 0.2,
                                val_err = c(0.95, 0.9, 0.87, 0.86))
  expect_equal(r$diagnosis, A[["uf.diag"]])
  expect_close(r$plateau_slope, A[["uf.slope"]], tol = 1e-8)
  expect_close(r$gap, A[["uf.gap"]])
  expect_true(r$converged)

  r <- morie_geron_curse_dimensionality(10, 1000)
  expect_close(r$nn_distance, A[["cod.nn"]])
  expect_close(r$mean_pairwise_distance, A[["cod.mean"]])
  expect_close(r$border_fraction, A[["cod.border"]])
  expect_close(r$sparsity_factor, A[["cod.sparse"]])
  expect_close(r$n_for_density, A[["cod.ndens"]], tol = 1e-6)

  r <- morie_geron_johnson_lindenstrauss(1000, 0.2)
  expect_close(r$d_min, A[["jl.dmin"]])
  expect_close(r$d_min_exact, A[["jl.exact"]])
  expect_close(morie_geron_johnson_lindenstrauss(1000, c(0.1, 0.3))$d_min,
               A[["jl.dminv"]])
})

test_that("standardization, encodings and imputation match Python", {
  X <- matrix(c(1, 10, 2, 20, 4, 25, 5, 45), nrow = 4, byrow = TRUE)
  r <- morie_geron_standardization(X)
  expect_close(r$X_std, A[["stz.Z"]])
  expect_close(r$mean, A[["stz.mu"]])
  expect_close(r$scale, A[["stz.sd"]])
  # ddof = 0 is the POPULATION sd, not R's sd()
  expect_close(r$scale, apply(X, 2, function(c) sqrt(mean((c - mean(c))^2))))
  expect_close(morie_geron_standardization(X, ddof = 1)$scale, A[["stz.sd1"]])
  expect_close(morie_geron_standardization(X, ddof = 1)$scale, apply(X, 2, sd))

  cats <- matrix(c("a", "x", "b", "x", "a", "y"), nrow = 3, byrow = TRUE)
  r <- morie_geron_one_hot_encoding(cats)
  expect_close(r$encoded, A[["ohe.enc"]])
  expect_equal(r$names, A[["ohe.names"]])
  expect_close(r$n_columns, A[["ohe.ncol"]])
  r <- morie_geron_one_hot_encoding(cats, drop_first = TRUE)
  expect_close(r$encoded, A[["ohe.enc1"]])
  expect_close(r$n_columns, A[["ohe.ncol1"]])

  r <- morie_geron_ordinal_encoding(matrix(c("c", "x", "a", "y", "b", "x"),
                                           nrow = 3, byrow = TRUE))
  expect_close(r$encoded, A[["ord.enc"]])
  expect_close(r$n_categories, A[["ord.ncat"]])

  r <- morie_geron_imputation_median(matrix(c(1, 10, NA, 20, 3, NA, 5, 40),
                                            nrow = 4, byrow = TRUE))
  expect_close(r$X_imputed, A[["imp.X"]])
  expect_close(r$statistics, A[["imp.stats"]])
  expect_close(r$n_missing, A[["imp.nmiss"]])
  expect_close(r$missing_fraction, A[["imp.frac"]])
})

