test_that("optimiser steps match Python", {
  g <- c(0.5, -1.5, 0.25)
  r <- morie_geron_momentum(g, v = c(0.1, 0, -0.2), beta = 0.8, eta = 0.05,
                            theta = c(1, 1, 1))
  expect_close(r$theta, A[["mom.theta"]])
  expect_close(r$v, A[["mom.v"]])
  expect_close(r$terminal_step, A[["mom.term"]])
  expect_close(morie_geron_momentum(g, v = c(0.1, 0, -0.2), beta = 0.8,
                                    eta = 0.05, theta = c(1, 1, 1),
                                    nesterov = TRUE)$theta,
               A[["mom.theta_nes"]])

  r <- morie_geron_nesterov(g, v = c(0.1, 0, -0.2), beta = 0.8, eta = 0.05,
                            theta = c(1, 1, 1))
  expect_close(r$theta, A[["nag.theta"]])
  expect_close(r$lookahead, A[["nag.look"]])
  expect_close(r$v, A[["nag.v"]])
  # the callable arm evaluates the gradient AT the look-ahead point
  rc <- morie_geron_nesterov(function(th) th * 0 + g, v = c(0.1, 0, -0.2),
                             beta = 0.8, eta = 0.05, theta = c(1, 1, 1))
  expect_close(rc$theta, A[["nag.theta"]])

  r <- morie_geron_nadam(g, m = c(0.05, 0, 0), v = c(0.01, 0.02, 0),
                         eta = 0.01, t = 3, theta = c(1, 1, 1))
  expect_close(r$theta, A[["nadm.theta"]])
  expect_close(r$m_hat, A[["nadm.mhat"]])
  expect_close(r$v_hat, A[["nadm.vhat"]])
  expect_close(r$step, A[["nadm.step"]])
})

test_that("SGD and mini-batch GD match Python", {
  X <- matrix(c(1, 0.5, 1, 1.5, 1, 2.5, 1, 4), nrow = 4, byrow = TRUE)
  y <- c(1, 2.2, 2.8, 4.4)
  r <- morie_geron_sgd_update(X, y, c(0.5, 0.8), eta = 0.05, seed = 11)
  expect_close(r$index, A[["sgdu.index"]])
  expect_close(r$theta, A[["sgdu.theta"]])
  expect_close(r$gradient, A[["sgdu.grad"]])
  expect_close(r$batch_gradient, A[["sgdu.bgrad"]])
  expect_close(r$residual, A[["sgdu.resid"]])
  # explicit index must reproduce the LCG-picked row exactly
  expect_close(morie_geron_sgd_update(X, y, c(0.5, 0.8), eta = 0.05,
                                      index = A[["sgdu.index"]])$theta,
               A[["sgdu.theta"]])

  # HONEST DIVERGENCE: numpy's default_rng(3).permutation cannot be
  # reproduced in R, so the permutation is an anchor and is fed in.
  r <- morie_geron_minibatch_gd(X, y, c(0.5, 0.8), 0.05, 2,
                                order = A[["mbgd.perm"]], n_steps = 2)
  expect_close(r$theta, A[["mbgd.theta"]])
  expect_close(r$gradient, A[["mbgd.grad"]])
  expect_close(r$full_gradient, A[["mbgd.full"]])
  expect_close(r$mse, A[["mbgd.mse"]])
  expect_close(r$batch_indices, A[["mbgd.idx"]])
  # b = m reduces to batch GD: one step equals the full-gradient step
  rb <- morie_geron_minibatch_gd(X, y, c(0.5, 0.8), 0.05, 4, n_steps = 1)
  full0 <- (2 / 4) * as.numeric(t(X) %*% (X %*% c(0.5, 0.8) - y))
  expect_close(rb$theta, c(0.5, 0.8) - 0.05 * full0)
})

test_that("logistic probability, cost and gradient match Python", {
  X <- matrix(c(1, 0, 1, 1, 1, 2, 1, 3), nrow = 4, byrow = TRUE)
  y <- c(0, 0, 1, 1)
  th <- c(-1.5, 1)
  r <- morie_geron_logistic_probability(X, th)
  expect_close(r$p_hat, A[["logp.p"]])
  expect_close(r$logits, A[["logp.logits"]])
  expect_close(r$prediction, A[["logp.pred"]])

  r <- morie_geron_logistic_cost(X, y, th)
  expect_close(r$cost, A[["logcl.cost"]])
  expect_close(r$per_instance, A[["logcl.per"]])
  expect_close(r$baseline_cost, A[["logcl.base"]])
  # INDEPENDENT ROUTE: the naive -y log p - (1-y) log(1-p) form.
  p <- morie_geron_logistic_probability(X, th)$p_hat
  expect_close(r$cost, mean(-(y * log(p) + (1 - y) * log(1 - p))))

  r <- morie_geron_logistic_gradient(X, y, th)
  expect_close(r$gradient, A[["logg.grad"]])
  expect_close(r$hessian, A[["logg.hess"]])
  # INDEPENDENT ROUTE: finite differences on the cost.
  h <- 1e-6
  fd <- vapply(seq_along(th), function(j) {
    up <- th; dn <- th; up[j] <- up[j] + h; dn[j] <- dn[j] - h
    (morie_geron_logistic_cost(X, y, up)$cost -
       morie_geron_logistic_cost(X, y, dn)$cost) / (2 * h)
  }, numeric(1))
  expect_close(r$gradient, fd, tol = 1e-6)
  # Hessian is PSD, which is what makes the cost convex
  expect_true(all(eigen(r$hessian, only.values = TRUE)$values >= -1e-12))
})

test_that("perceptron, Hebb and residual block match Python", {
  r <- morie_geron_perceptron(matrix(c(2, 1, 3, 2, -1, -2, -2, -1), nrow = 4,
                                     byrow = TRUE),
                              c(1, 1, 0, 0), eta = 0.5, n_iter = 20)
  expect_close(r$w, A[["pcpt.w"]])
  expect_close(r$bias, A[["pcpt.b"]])
  expect_close(r$accuracy, A[["pcpt.acc"]])
  expect_close(r$mistakes_per_epoch, A[["pcpt.mist"]])
  expect_true(r$converged)
  # XOR is not linearly separable: the perceptron never converges
  rx <- morie_geron_perceptron(matrix(c(0, 0, 0, 1, 1, 0, 1, 1), nrow = 4,
                                      byrow = TRUE),
                               c(0, 1, 1, 0), eta = 1, n_iter = 6)
  expect_false(rx$converged)
  expect_close(rx$accuracy, A[["pcpt.xor_acc"]])

  r <- morie_geron_hebb_rule(matrix(c(1, 0.5, 0, 2), nrow = 2, byrow = TRUE),
                             matrix(c(1, 0.5), ncol = 1), eta = 0.2)
  expect_close(r$dW, A[["hebb.dW"]])
  expect_close(r$norm_after, A[["hebb.after"]])
  expect_true(length(r$warnings) > 0)   # unbounded growth is flagged

  r <- morie_geron_resnet(c(1, 2, 3), function(a) a * 0.5)
  expect_close(r$y, A[["resn.y"]])
  expect_close(r$residual_fraction, A[["resn.frac"]])
  expect_close(r$y, c(1, 2, 3) + c(1, 2, 3) * 0.5)
})

