test_that("value function matches Python and iterated policy evaluation", {
  P <- A[["mdp.P"]]
  R <- A[["mdp.R"]]
  r <- morie_geron_value_function(1, c(0, 1, 0), 0.9, P = P, R = R)
  expect_close(r$V, A[["vf.V"]])
  expect_close(r$value, A[["vf.value"]])
  expect_close(r$r_pi, A[["vf.rpi"]])
  expect_close(r$P_pi, A[["vf.Ppi"]])
  expect_close(r$residual, A[["vf.resid"]], tol = 1e-10)

  # INDEPENDENT ROUTE: iterated policy evaluation, no linear solve.
  V <- rep(0, 3)
  for (it in seq_len(4000)) {
    V <- r$r_pi + 0.9 * as.numeric(r$P_pi %*% V)
  }
  expect_close(r$V, V, tol = 1e-8)

  rs <- morie_geron_value_function(0, A[["mdp.pi"]], 0.85, P = P, R = R)
  expect_close(rs$V, A[["vf.Vstoch"]])
})

test_that("tabular RL replays draw for draw", {
  r <- morie_geron_td_learning(c(0, 0, 0), c(0, 1, 0, 2), c(1, 0, 2, -1),
                              c(1, 2, 1, 2), alpha = 0.5, gamma = 0.9,
                              terminal = c(FALSE, FALSE, FALSE, TRUE))
  expect_close(r$V, A[["td.V"]])
  expect_close(r$td_error, A[["td.err"]])
  expect_close(r$target, A[["td.target"]])
  # INDEPENDENT ROUTE: replay the four transitions by hand, in order.
  V <- c(0, 0, 0); a <- 0.5; g <- 0.9
  V[1] <- V[1] + a * (1 + g * V[2] - V[1])
  V[2] <- V[2] + a * (0 + g * V[3] - V[2])
  V[1] <- V[1] + a * (2 + g * V[2] - V[1])
  V[3] <- V[3] + a * (-1 - V[3])          # terminal: no bootstrap
  expect_close(r$V, V)

  Q <- matrix(c(0, 1, 2, -1), nrow = 2, byrow = TRUE)
  r <- morie_geron_q_learning(Q, 0, 1, 0.5, 1, 0.5, 0.9)
  expect_close(r$Q, A[["ql.Q"]])
  expect_close(r$td_error, A[["ql.td"]])
  expect_close(r$target, A[["ql.target"]])
  expect_close(r$max_next, A[["ql.maxnext"]])
  expect_close(r$target, 0.5 + 0.9 * max(Q[2, ]))
  rd <- morie_geron_q_learning(Q, 0, 1, 0.5, 1, 0.5, 0.9, done = TRUE)
  expect_close(rd$td_error, A[["ql.td_done"]])
  expect_true(is.nan(rd$max_next))

  r <- morie_geron_credit_assignment(c(1, 0, 2, -1), gamma = 0.9, lam = 0.5)
  expect_close(r$raw_returns, A[["crd.ret"]])
  expect_close(r$eligibility, A[["crd.elig"]])
  expect_close(r$credit, A[["crd.credit"]])
  expect_close(r$discounted_rewards, A[["crd.disc"]])
  expect_close(r$total_return, A[["crd.total"]])
  # INDEPENDENT ROUTE: the return at t = 0 is the discounted sum.
  expect_close(r$total_return, sum(0.9^(0:3) * c(1, 0, 2, -1)))
  rn <- morie_geron_credit_assignment(c(1, 0, 2, -1), gamma = 0.9,
                                      normalize = TRUE)
  expect_close(rn$returns, A[["crd.norm"]])
})

test_that("hard voting matches Python with smallest-label tie-breaking", {
  models <- list(function(X) c(0, 1, 1, 0),
                 function(X) c(0, 1, 0, 0),
                 function(X) c(1, 1, 0, 1))
  r <- morie_geron_voting_hard(models, matrix(c(0, 1, 2, 3), ncol = 1),
                               y_true = c(0, 1, 0, 0))
  expect_close(r$predicted, A[["vth.pred"]])
  expect_close(r$votes, A[["vth.votes"]])
  expect_close(r$accuracy, A[["vth.acc"]])
  expect_close(r$member_accuracy, A[["vth.member"]])
  expect_close(r$agreement, A[["vth.agree"]])
  # identical members give an ensemble exactly as good as one of them
  same <- list(function(X) c(0, 1, 1, 0), function(X) c(0, 1, 1, 0))
  rs <- morie_geron_voting_hard(same, matrix(c(0, 1, 2, 3), ncol = 1),
                                y_true = c(0, 1, 0, 0))
  expect_close(rs$accuracy, rs$member_accuracy[1])
})

test_that("CART and the classification tree match Python", {
  XT <- matrix(c(1, 2, 3, 4), ncol = 1)
  r <- morie_geron_cart_algorithm(XT, c(0, 0, 1, 1))
  expect_close(r$tree$feature, A[["cart.feature"]])
  expect_close(r$tree$threshold, A[["cart.threshold"]])
  expect_close(r$n_leaves, A[["cart.leaves"]])
  expect_close(r$depth, A[["cart.depth"]])
  expect_close(r$train_accuracy, A[["cart.acc"]])
  expect_close(r$predictions, A[["cart.pred"]])
  expect_close(r$feature_importances, A[["cart.imp"]])
  # greedy CART cannot represent XOR at depth 1 but can at depth 2
  XX <- matrix(c(0, 0, 0, 1, 1, 0, 1, 1), nrow = 4, byrow = TRUE)
  YX <- c(0, 1, 1, 0)
  expect_close(morie_geron_cart_algorithm(XX, YX, max_depth = 1)$train_accuracy,
               A[["cart.xor1"]])
  expect_close(morie_geron_cart_algorithm(XX, YX, max_depth = 2)$train_accuracy,
               A[["cart.xor2"]])
  r2 <- morie_geron_cart_algorithm(XT, c(1, 1, 5, 5), criterion = "mse",
                                   max_depth = 1)
  expect_close(r2$predictions, A[["cart.mse_pred"]])
  expect_close(r2$train_mse, A[["cart.mse"]])

  XC <- matrix(c(1, 5, 2, 4, 3, 6, 6, 1, 7, 2, 8, 0.5), nrow = 6, byrow = TRUE)
  YC <- c(0, 0, 1, 1, 2, 2)
  r <- morie_geron_classification_tree(XC, YC, criterion = "entropy",
                                       max_depth = 3)
  expect_close(r$probabilities, A[["cdt.proba"]])
  expect_close(r$classes, A[["cdt.classes"]])
  expect_close(r$train_accuracy, A[["cdt.acc"]])
  expect_close(r$n_leaves, A[["cdt.leaves"]])
  expect_close(r$feature_importances, A[["cdt.imp"]])
  # leaf frequencies are probabilities: every row sums to one
  expect_close(rowSums(r$probabilities), rep(1, 6))
})

test_that("softmax cross-entropy, its gradient and the MLP match Python", {
  XE <- matrix(c(1, 0.5, 0.5, 2, -1, 1, 2, -0.5), nrow = 4, byrow = TRUE)
  THE <- matrix(c(0.4, -0.3, 0.1, 0.2, 0.7, -0.6), nrow = 2, byrow = TRUE)
  YE <- c(0, 1, 2, 0)
  r <- morie_geron_cross_entropy_cost(XE, YE, THE)
  expect_close(r$cost, A[["cec.cost"]])
  expect_close(r$probabilities, A[["cec.P"]])
  expect_close(r$per_sample_cost, A[["cec.per"]])
  expect_close(r$accuracy, A[["cec.acc"]])
  expect_close(r$chance_cost, A[["cec.chance"]])
  expect_close(rowSums(r$probabilities), rep(1, 4))

  g <- morie_geron_cross_entropy_gradient(XE, YE, THE)
  expect_close(g$gradient, A[["ceg.G"]])
  expect_close(g$grad_norm, A[["ceg.norm"]])
  expect_close(g$column_sum_max_abs, A[["ceg.colsum"]], tol = 1e-12)
  # softmax is over-parameterised: each gradient row sums to zero
  expect_close(rowSums(g$gradient), rep(0, 2), tol = 1e-12)
  # INDEPENDENT ROUTE: finite differences on the cost surface.
  h <- 1e-6
  fd <- THE * 0
  for (i in seq_len(2)) for (j in seq_len(3)) {
    up <- THE; dn <- THE
    up[i, j] <- up[i, j] + h; dn[i, j] <- dn[i, j] - h
    fd[i, j] <- (morie_geron_cross_entropy_cost(XE, YE, up)$cost -
                   morie_geron_cross_entropy_cost(XE, YE, dn)$cost) / (2 * h)
  }
  expect_close(g$gradient, fd, tol = 1e-6)

  XC <- matrix(c(1, 5, 2, 4, 3, 6, 6, 1, 7, 2, 8, 0.5), nrow = 6, byrow = TRUE)
  YC <- c(0, 0, 1, 1, 2, 2)
  m <- morie_geron_classification_mlp(XC, YC, hidden_sizes = 3, epochs = 40,
                                      lr = 0.2, seed = 5)
  expect_close(m$loss_history, A[["clsn.hist"]])
  expect_close(m$final_loss, A[["clsn.final"]])
  expect_close(m$accuracy, A[["clsn.acc"]])
  expect_close(m$n_params, A[["clsn.params"]])
  expect_close(m$weights[[1]], A[["clsn.W0"]])
  expect_close(m$weights[[2]], A[["clsn.W1"]])
  expect_close(m$probabilities, A[["clsn.P"]])
  # INDEPENDENT ROUTE: parameter count against the layer algebra.
  expect_close(m$n_params, (2 * 3 + 3) + (3 * 3 + 3))
})

