test_that("classification + localization matches Python", {
  OUTM <- A[["clc.out"]]
  r <- morie_geron_classification_localization(NULL, function(im) OUTM,
                                               gt_class = c(0, 1),
                                               gt_box = A[["clc.gtb"]],
                                               alpha = 0.01)
  expect_close(r$class_probs, A[["clc.P"]])
  expect_close(r$predicted_class, A[["clc.pred"]])
  expect_close(r$iou, A[["clc.iou"]])
  expect_close(r$loss_class, A[["clc.lcls"]])
  expect_close(r$loss_box, A[["clc.lbox"]])
  expect_close(r$loss, A[["clc.loss"]])
