  # INDEPENDENT ROUTE: the combined loss is the weighted sum of the heads.
  expect_close(r$loss, r$loss_class + 0.01 * r$loss_box)
  expect_true(all(r$iou >= 0 & r$iou <= 1))
})

test_that("computational graph matches Python and its own finite differences", {
  expr <- list("mul", list("add", "x", 2), list("sin", "y"))
  r <- morie_geron_computational_graph(expr, list(x = 1.5, y = 0.7))
  expect_close(r$value, A[["cgrf.value"]])
  expect_close(r$grad$x, A[["cgrf.gx"]])
  expect_close(r$grad$y, A[["cgrf.gy"]])
  expect_close(r$fd_check$x, A[["cgrf.fdx"]])
  expect_close(r$fd_check$y, A[["cgrf.fdy"]])
  expect_close(r$n_nodes, A[["cgrf.nodes"]])
  # INDEPENDENT ROUTE: reverse mode against the module's own central
  # differences, and against the closed form.
  expect_close(r$grad$x, r$fd_check$x, tol = 1e-6)
  expect_close(r$grad$y, r$fd_check$y, tol = 1e-6)
  expect_close(r$grad$x, sin(0.7))
  expect_close(r$grad$y, (1.5 + 2) * cos(0.7))

  expr2 <- list("log", list("add", list("square", "x"), 1))
  r <- morie_geron_computational_graph(expr2, list(x = 2))
  expect_close(r$value, A[["cgrf2.value"]])
  expect_close(r$grad$x, A[["cgrf2.gx"]])
  expect_close(r$fd_check$x, A[["cgrf2.fdx"]])
  expect_close(r$grad$x, 2 * 2 / (2^2 + 1))
})

